import CryptoKit
import Foundation

/// The app's App Attest calls. SubcFed never touches DeviceCheck itself and
/// never stores the key: the app generates the key and attests it over the
/// pairing client-data hash. SubcFed requests a session assertion over the
/// session's client-data hash when a provider and the handshake hash are
/// both available; an empty assertion sends no frame. The provider uses the key generated by the app;
/// SubcFed never stores that key.
public protocol FedAppAttestProvider: Sendable {
    /// Generates the app's attestation key (or reuses the stored one) and
    /// attests it over `clientDataHash`, which is already
    /// `SHA-256(SHA-256(label || handshakeHash))` for the pairing at hand.
    /// Returns the raw key identifier and the raw CBOR attestation object.
    func attestPairing(clientDataHash: Data) async throws -> FedPairingAttestation
    /// Asserts the stored key over `clientDataHash` for one ordinary session.
    /// Returns the raw CBOR assertion object.
    func sessionAssertion(clientDataHash: Data) async throws -> Data
}

/// Raw pairing attestation material from the app provider.
public struct FedPairingAttestation: Sendable, Equatable {
    public let keyID: Data
    public let attestation: Data

    public init(keyID: Data, attestation: Data) {
        self.keyID = keyID
        self.attestation = attestation
    }
}

/// Wire shapes for the two optional attestation frames. They are kept outside
/// `FedFrameType` so embedding apps that switch exhaustively over that enum
/// keep compiling when this protocol is adopted.
public enum FedAppAttestCodec {
    public static let pairingAttestationType = "pairing_attestation"
    public static let sessionAssertionType = "session_assertion"
    public static let frameTypes: Set<String> = [pairingAttestationType, sessionAssertionType]
    /// Header cap for the pairing frame, which carries two base64url blobs.
    public static let maximumPairingHeaderBytes = 16_384

    static let pairingLabel = Data("ckpair-attest-v1".utf8)
    static let sessionLabel = Data("ck-session-assert-v1".utf8)

    // MARK: - Challenges

    /// Inner challenge both sides derive locally: `SHA-256(label || h)`.
    public static func pairingChallenge(handshakeHash h: Data) -> Data {
        var input = pairingLabel
        input.append(h)
        return Data(SHA256.hash(data: input))
    }

    /// Inner challenge both sides derive locally: `SHA-256(label || h)`.
    public static func sessionChallenge(handshakeHash h: Data) -> Data {
        var input = sessionLabel
        input.append(h)
        return Data(SHA256.hash(data: input))
    }

    /// Client-data hash the provider signs: `SHA-256(challenge)`.
    public static func clientDataHash(challenge: Data) -> Data {
        Data(SHA256.hash(data: challenge))
    }

    /// Pairing client-data hash in one step: `SHA-256(SHA-256(label || h))`.
    public static func pairingClientDataHash(handshakeHash h: Data) -> Data {
        clientDataHash(challenge: pairingChallenge(handshakeHash: h))
    }

    /// Session client-data hash in one step: `SHA-256(SHA-256(label || h))`.
    public static func sessionClientDataHash(handshakeHash h: Data) -> Data {
        clientDataHash(challenge: sessionChallenge(handshakeHash: h))
    }

    // MARK: - Builders

    public static func pairingAttestationFrame(keyID: Data, attestation: Data) -> FedFrame {
        FedFrame(
            type: pairingAttestationType,
            fields: [
                "attestation": .string(base64URLEncode(attestation)),
                "key_id": .string(base64URLEncode(keyID)),
            ]
        )
    }

    public static func sessionAssertionFrame(assertion: Data) -> FedFrame {
        FedFrame(
            type: sessionAssertionType,
            fields: ["assertion": .string(base64URLEncode(assertion))]
        )
    }

    // MARK: - Base64url

    /// Unpadded RFC 4648 §5 encoding used by both attestation headers.
    public static func base64URLEncode(_ data: Data) -> String {
        data.base64EncodedString()
            .replacingOccurrences(of: "+", with: "-")
            .replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: "=", with: "")
    }

    static func base64URLDecode(_ value: String) -> Data? {
        var base64 = value
            .replacingOccurrences(of: "-", with: "+")
            .replacingOccurrences(of: "_", with: "/")
        base64.append(String(repeating: "=", count: (4 - base64.count % 4) % 4))
        return Data(base64Encoded: base64)
    }

    // MARK: - Validation (called by FedFrameCodec)

    static func validateHeader(
        _ header: FedJSONObject,
        type: String,
        negotiationComplete: Bool,
        negotiatedFeatures _: Set<String>
    ) throws {
        if type == sessionAssertionType {
            guard negotiationComplete else { throw FedFrameError.unknownTypeBeforeNegotiation(type) }
            guard Set(header.keys) == ["type", "assertion"],
                  case .string(let text) = header["assertion"],
                  !text.isEmpty,
                  base64URLDecode(text) != nil
            else { throw FedFrameError.invalidHeaderField(type: type, field: "assertion") }
            return
        }
        // Pairing attestation rides the pairing session, which never completes
        // hello negotiation, so it is valid before negotiation as well.
        guard Set(header.keys) == ["type", "key_id", "attestation"],
              case .string(let keyID) = header["key_id"],
              !keyID.isEmpty,
              base64URLDecode(keyID) != nil,
              case .string(let attestation) = header["attestation"],
              !attestation.isEmpty,
              base64URLDecode(attestation) != nil
        else { throw FedFrameError.invalidHeaderField(type: type, field: "key_id") }
        let encoded: Data
        do {
            encoded = try header.jsonData()
        } catch {
            throw FedFrameError.invalidHeaderField(type: type, field: "key_id")
        }
        guard encoded.count <= maximumPairingHeaderBytes else {
            throw FedFrameError.headerTooLarge(declared: UInt32(encoded.count), maximum: UInt32(maximumPairingHeaderBytes))
        }
    }

    static func validateBody(_ body: Data, type: String) throws {
        guard body.isEmpty else {
            throw FedFrameError.bodylessFrame(type: type, declared: UInt32(body.count))
        }
    }
}
